def findKthNumber(m, n, k):
    # count how many entries in the m x n table are <= x
    def count_le(x):
        total = 0
        for i in range(1, m + 1):
            total += min(x // i, n)  # row i holds i, 2i, ... ; how many are <= x
        return total

    lo, hi = 1, m * n
    while lo < hi:
        mid = (lo + hi) // 2
        if count_le(mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
